{"code": "def run(inputs: dict) -> dict:
    """
    Рассчитывает маржу EBITDA как (EBITDA / Выручка) * 100.
    Ожидает на входе ExtractedMetric с concept="EBITDA" и concept="REVENUE"
    за одинаковый период и в одинаковых единицах.
    """
    metrics = inputs.get("ExtractedMetric", [])

    ebitda_val = None
    revenue_val = None
    period = None
    unit = None

    for m in metrics:
        concept = m.get("concept")
        sf = m.get("scalar_fact")
        if not sf:
            continue

        val = sf.get("value")
        m_unit = sf.get("unit")
        m_period = sf.get("period_ref")

        if concept == "EBITDA":
            if ebitda_val is not None:
                raise ValueError("Найдено несколько значений EBITDA")
            ebitda_val = val
            if ebitda_val is None:
                raise ValueError("Не найдено значение EBITDA")
            if period is None:
                period = m_period
            elif period != m_period:
                raise ValueError(f"Несовпадающие периоды: {period} и {m_period}")
            if unit is None:
                unit = m_unit
            elif unit != m_unit:
                raise ValueError(f"Несовпадающие единицы: {unit} и {m_unit}")

        elif concept == "REVENUE":
            if revenue_val is not None:
                raise ValueError("Найдено несколько значений REVENUE")
            revenue_val = val
            if revenue_val is None:
                raise ValueError("Не найдено значение REVENUE")
            if period is None:
                period = m_period
            elif period != m_period:
                raise ValueError(f"Несовпадающие периоды: {period} и {m_period}")
            if unit is None:
                unit = m_unit
            elif unit != m_unit:
                raise ValueError(f"Несовпадающие единицы: {unit} и {m_unit}")

    if ebitda_val is None:
        raise ValueError("Не найден ExtractedMetric с concept='EBITDA'")
    if revenue_val is None:
        raise ValueError("Не найден ExtractedMetric с concept='REVENUE'")
    if revenue_val == 0:
        raise ValueError("Выручка равна нулю, расчёт маржи невозможен")

    margin_pct = (ebitda_val / revenue_val) * 100.0

    return {"margin_pct": margin_pct}
